/// Client metadata supplied during handshake.
#[derive(Debug, Clone)]
pub struct ClientConfig {
    pub name: String,
    pub group_maker: clonk_engine::LegacyCString,
    pub kind: ParticipantKind,
    /// Build advertised during `PID_Conn` and expected from every peer in the
    /// target game. Reference-backed joins set this from the host reference;
    /// unresolved direct joins retain [`CURRENT_GAME_BUILD`].
    pub compatibility_build: i32,
    pub password: clonk_engine::LegacyCString,
    pub resource_directory: Option<PathBuf>,
    pub bootstrap_local_candidates: crate::ClientBootstrapLocalCandidates,
    pub local_system_path: Option<PathBuf>,
    pub local_resource_roots: Vec<PathBuf>,
    /// TCP endpoint accepted for already joined client-to-client mesh routes.
    /// `None` keeps the listener disabled for embedders that do not expose a
    /// network endpoint.
    pub mesh_tcp_bind_address: Option<SocketAddr>,
    /// Reliable-UDP endpoint shared by outbound and inbound mesh routes.
    pub mesh_udp_bind_address: Option<SocketAddr>,
    /// Resolved per-family netpuncher endpoints advertised by the host.
    pub mesh_punchers: Vec<ClientMeshPuncherConfig>,
}

impl ClientConfig {
    pub fn new(name: impl Into<String>, kind: ParticipantKind) -> Self {
        let name = name.into();
        let group_maker = clonk_engine::LegacyCString::from_bytes(name.as_bytes().to_vec())
            .unwrap_or_default();
        Self {
            name,
            group_maker,
            kind,
            compatibility_build: CURRENT_GAME_BUILD,
            password: clonk_engine::LegacyCString::default(),
            resource_directory: Some(default_client_resource_directory()),
            bootstrap_local_candidates: crate::ClientBootstrapLocalCandidates::default(),
            local_system_path: None,
            local_resource_roots: Vec::new(),
            mesh_tcp_bind_address: None,
            mesh_udp_bind_address: None,
            mesh_punchers: Vec::new(),
        }
    }

    pub fn with_password(mut self, password: clonk_engine::LegacyCString) -> Self {
        self.password = password;
        self
    }

    pub fn with_compatibility_build(mut self, build: i32) -> Self {
        self.compatibility_build = build;
        self
    }

    pub fn with_group_maker(mut self, group_maker: clonk_engine::LegacyCString) -> Self {
        self.group_maker = group_maker;
        self
    }

    pub fn with_resource_directory(mut self, resource_directory: impl Into<PathBuf>) -> Self {
        self.resource_directory = Some(resource_directory.into());
        self
    }

    pub fn with_bootstrap_local_candidates(
        mut self,
        candidates: crate::ClientBootstrapLocalCandidates,
    ) -> Self {
        self.bootstrap_local_candidates = candidates;
        self
    }

    pub fn with_local_system_path(mut self, path: impl Into<PathBuf>) -> Self {
        self.local_system_path = Some(path.into());
        self
    }

    pub fn with_local_resource_roots(
        mut self,
        roots: impl IntoIterator<Item = impl Into<PathBuf>>,
    ) -> Self {
        self.local_resource_roots = roots.into_iter().map(Into::into).collect();
        self
    }

    pub fn with_mesh_tcp_bind_address(mut self, address: SocketAddr) -> Self {
        self.mesh_tcp_bind_address = Some(address);
        self
    }

    pub fn with_mesh_udp_bind_address(mut self, address: SocketAddr) -> Self {
        self.mesh_udp_bind_address = Some(address);
        self
    }

    pub fn with_mesh_punchers(
        mut self,
        punchers: impl IntoIterator<Item = ClientMeshPuncherConfig>,
    ) -> Self {
        self.mesh_punchers = punchers.into_iter().collect();
        self
    }
}

fn default_client_resource_directory() -> PathBuf {
    // Application callers replace this with Config.Network.WorkPath. Library
    // callers still need a real ResList backend, so keep their default out of
    // the current source tree while preserving the stock `Network` role.
    std::env::temp_dir()
        .join(format!("legacyclonk-{}", std::process::id()))
        .join("Network")
}

async fn bind_client_mesh_tcp_listener(bind_address: SocketAddr) -> io::Result<TcpListener> {
    if !bind_address.ip().is_unspecified() {
        return TcpListener::bind(bind_address).await;
    }
    let socket = socket2::Socket::new(
        socket2::Domain::IPV6,
        socket2::Type::STREAM,
        Some(socket2::Protocol::TCP),
    )?;
    socket.set_only_v6(false)?;
    socket.set_reuse_address(true)?;
    socket.set_nonblocking(true)?;
    let dual_stack_address = SocketAddr::from(([0_u16; 8], bind_address.port()));
    socket.bind(&dual_stack_address.into())?;
    socket.listen(128)?;
    let listener = std::net::TcpListener::from(socket);
    TcpListener::from_std(listener)
}

/// Keeps in-process session tests operational. The app explicitly disables
/// this placeholder and must publish real scenario/dynamic resource cores
/// before admitting peers; these synthetic cores cannot boot a stock client.
fn synthetic_join_snapshot(
    local_core: clonk_engine::ClientCoreControlData,
    max_players: usize,
) -> HostJoinSnapshot {
    let empty_players = crate::PlayerInfoListSnapshot {
        last_player_id: 0,
        clients: Vec::new(),
    };
    HostJoinSnapshot {
        dynamic: clonk_engine::NetworkResourceCore {
            resource_type: 2,
            id: 1,
            derived_id: -1,
            loadable: true,
            file_size: 1,
            file_crc: 0,
            contents_crc: 0,
            filename: clonk_engine::LegacyCString::from_bytes(b"Dynamic.c4d".to_vec())
                .expect("static dynamic resource name is NUL-free"),
            ..Default::default()
        },
        dynamic_tick: 0,
        parameters: crate::JoinGameParametersEnvelope {
            random_seed: 0,
            startup_player_count: 0,
            max_players: i32::try_from(max_players).unwrap_or(i32::MAX),
            use_fair_crew: false,
            fair_crew_forced: false,
            fair_crew_strength: 0,
            allow_debug: true,
            is_network_game: true,
            control_rate: 1,
            auto_frame_skip: false,
            rules: Vec::new(),
            goals: Vec::new(),
            league: clonk_engine::LegacyCString::default(),
            league_address: clonk_engine::LegacyCString::default(),
            title: clonk_engine::LegacyCString::from_bytes(b"No title".to_vec())
                .expect("static title is NUL-free"),
            scenario: clonk_engine::NetworkResourceCore {
                resource_type: 1,
                id: 2,
                derived_id: -1,
                loadable: true,
                file_size: 1,
                file_crc: 0,
                contents_crc: 0,
                filename: clonk_engine::LegacyCString::from_bytes(b"Scenario.c4s".to_vec())
                    .expect("static scenario resource name is NUL-free"),
                ..Default::default()
            },
            game_resources: Vec::new(),
            player_infos: empty_players.clone(),
            restore_player_infos: empty_players,
            teams: crate::JoinTeamListSnapshot {
                active: 1,
                custom: 0,
                allow_hostility_change: 1,
                allow_team_switch: 0,
                auto_generate_teams: 1,
                last_team_id: 0,
                team_distribution: 0,
                team_colors: 0,
                max_script_players: 0,
                script_player_names: clonk_engine::LegacyCString::default(),
                random_team_count: 0,
                teams: Vec::new(),
            },
            clients: JoinClientRegistrySnapshot {
                clients: vec![local_core],
                local_client_id: Some(0),
            },
        },
    }
}

/// Events emitted by the host loop.
#[derive(Debug)]
pub enum HostEvent {
    /// Complete current address list for the host client after an
    /// AddAddrFromPuncher update. Reference invalidation waits for AssID.
    LocalAddressesChanged {
        local_addresses: Vec<crate::NetworkAddress>,
    },
    /// A family-specific AssID arrived. The complete IDs and current address
    /// list let the application rebuild one exact advertised reference.
    NetpuncherStateChanged {
        game_ids: NetpuncherGameIds,
        local_addresses: Vec<crate::NetworkAddress>,
    },
    /// The authoritative host barrier was opened or retargeted. Runtime
    /// control owns the actual drive-to-target/stop operation, so surface
    /// every accepted `ChangeGameStatus` rather than inferring it from raw
    /// client acknowledgements.
    StatusChanged(NetworkStatus),
    StatusCommitted(NetworkStatus),
    StatusAck {
        client_id: ClientId,
        status: NetworkStatus,
    },
    ActivationRequest {
        client_id: ClientId,
        tick: i32,
        waited_for: bool,
        ping_ms: i32,
    },
    PlayerInfoUpdate {
        client_id: ClientId,
        request: crate::PlayerInfoUpdateRequest,
    },
    LobbyCountdown {
        packet: LobbyCountdownPacket,
    },
    ReadyCheck {
        packet: ReadyCheckPacket,
    },
    ResourceAction(crate::ResourceCatalogAction),
    ResourceProgress {
        resource_id: i32,
        present_percent: u8,
    },
    ResourceComplete {
        resource_id: i32,
        core: clonk_engine::NetworkResourceCore,
        path: PathBuf,
        local: bool,
    },
    ResourceLoadFailed {
        resource_id: i32,
    },
    ResourceDeriveUnsupported {
        core: clonk_engine::NetworkResourceCore,
    },
    ClientJoined {
        client_id: ClientId,
        name: String,
        kind: ParticipantKind,
    },
    ClientLeft {
        client_id: ClientId,
    },
    /// The final accepted route for a logical client was lost unexpectedly.
    /// Controlled synchronized removal, host shutdown, and loss of a route
    /// with a surviving fallback do not emit this event.
    ClientConnectionFailed {
        client_id: ClientId,
    },
    JoinDataNeeded {
        client_id: ClientId,
        current_control_tick: Tick,
    },
    Ready {
        packet: ControlPacket,
    },
    Direct {
        client_id: ClientId,
        delivery: ControlDelivery,
        data: Vec<u8>,
    },
    SyncScheduled {
        control_tick: Tick,
        controls: Vec<clonk_engine::ControlPacket>,
    },
    ExecSync {
        control_tick: Tick,
    },
    UnhandledPacket {
        client_id: Option<ClientId>,
        packet_type: u8,
    },
    TransportError {
        client_id: Option<ClientId>,
        error: String,
    },
}

/// Commands issued by the runtime to influence the host loop.
#[derive(Debug)]
pub enum HostCommand {
    ChangeStatus(NetworkStatus),
    BeginGo {
        status: NetworkStatus,
        join_allowed: bool,
        completion: oneshot::Sender<()>,
    },
    BroadcastStatusAck(NetworkStatus),
    ControlTickReached {
        tick: Tick,
        control_rate: i32,
        target_fps: i32,
        reached_at: tokio::time::Instant,
    },
    ControlTickConsumed {
        tick: Tick,
        consumed_at: tokio::time::Instant,
        client_ids: Vec<ClientId>,
        reset_performance: bool,
    },
    StatusReachedCurrent,
    StatusReached {
        status: NetworkStatus,
        actual_control_tick: i32,
    },
    SubmitLocal(ControlPacket),
    SubmitLobbyCountdown(LobbyCountdownPacket),
    SubmitReadyCheck(ReadyCheckPacket),
    BroadcastLeagueRoundResults(crate::LeagueRoundResultsPacket),
    SubmitPacket {
        delivery: ControlDelivery,
        data: Vec<u8>,
    },
    ExecSync {
        control_tick: Tick,
    },
    PublishJoinSnapshot(Box<HostJoinSnapshot>),
    PublishRuntimeDynamic {
        dynamic: Box<crate::LiveNetworkDynamic>,
        dynamic_tick: i32,
        parameters: Box<crate::JoinGameParametersEnvelope>,
        completion: oneshot::Sender<Result<clonk_engine::NetworkResourceCore, String>>,
    },
    RemoveRuntimeDynamic {
        completion: oneshot::Sender<Result<bool, String>>,
    },
    FailPendingJoinData {
        reason: clonk_engine::LegacyCString,
        completion: oneshot::Sender<usize>,
    },
    PublishPlayerResource {
        request: crate::ClientPlayerResourceRequest,
        completion: oneshot::Sender<Result<clonk_engine::NetworkResourceCore, String>>,
    },
    BeginResourceDerive {
        resource_id: i32,
        source_path: PathBuf,
        ownership: crate::ResourceFileOwnership,
        completion: oneshot::Sender<Result<crate::ResourceDerivation, String>>,
    },
    FinishResourceDerive {
        derivation: crate::ResourceDerivation,
        completion: oneshot::Sender<Result<clonk_engine::NetworkResourceCore, String>>,
    },
    SetJoinAllowed {
        allowed: bool,
        completion: oneshot::Sender<()>,
    },
    InspectRuntimeClientStates {
        tick: Tick,
        reset_performance: bool,
        completion: oneshot::Sender<Vec<RuntimeNetworkClientState>>,
    },
    SetPassword {
        password: Option<clonk_engine::LegacyCString>,
        completion: oneshot::Sender<()>,
    },
    InitNetpunchers {
        addresses: Vec<SocketAddr>,
        completion: oneshot::Sender<()>,
    },
    InspectRuntimeConnections {
        completion: oneshot::Sender<Vec<RuntimeNetworkConnection>>,
    },
    InspectLobbyClientTelemetry {
        client_ids: Vec<ClientId>,
        completion: oneshot::Sender<RuntimeLobbyClientTelemetry>,
    },
    DisconnectRuntimeConnection {
        connection_id: u32,
        completion: oneshot::Sender<bool>,
    },
    #[cfg(test)]
    InspectAcceptedRoutes {
        completion: oneshot::Sender<Vec<(u32, ClientId, u32)>>,
    },
    #[cfg(test)]
    InspectConnectedClients {
        completion: oneshot::Sender<Vec<ClientId>>,
    },
    Shutdown,
}

/// Handle for interacting with a running host loop.
#[derive(Debug)]
pub struct HostHandle {
    command_tx: mpsc::Sender<HostCommand>,
    event_rx: Option<mpsc::Receiver<HostEvent>>,
    shutdown_tx: Option<oneshot::Sender<()>>,
    join_handle: tokio::task::JoinHandle<()>,
    udp_local_addr: Option<SocketAddr>,
    io_statistics: crate::NetworkIoStatistics,
}

impl HostHandle {
    pub fn udp_local_addr(&self) -> Option<SocketAddr> {
        self.udp_local_addr
    }

    pub fn io_statistics(&self) -> crate::NetworkIoStatistics {
        self.io_statistics.clone()
    }

    pub fn events(&mut self) -> &mut mpsc::Receiver<HostEvent> {
        self.event_rx
            .as_mut()
            .expect("host event receiver already taken")
    }

    pub fn take_event_receiver(&mut self) -> mpsc::Receiver<HostEvent> {
        self.event_rx
            .take()
            .expect("host event receiver already taken")
    }

    pub async fn submit_local_control(&self, packet: ControlPacket) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::SubmitLocal(packet))
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    pub async fn submit_ready_check(&self, packet: ReadyCheckPacket) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::SubmitReadyCheck(packet))
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    pub async fn submit_lobby_countdown(
        &self,
        packet: LobbyCountdownPacket,
    ) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::SubmitLobbyCountdown(packet))
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    /// Broadcasts the host's final league result packet to every connected
    /// logical client as `PID_LeagueRoundResults`.
    pub async fn broadcast_league_round_results(
        &self,
        packet: crate::LeagueRoundResultsPacket,
    ) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::BroadcastLeagueRoundResults(packet))
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    pub async fn change_status(&self, status: NetworkStatus) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::ChangeStatus(status))
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    /// Applies the lobby's Go barrier and runtime admission policy as one
    /// host-loop operation. No pending admission request can be processed
    /// between the two state changes.
    pub async fn begin_go(
        &self,
        status: NetworkStatus,
        join_allowed: bool,
    ) -> Result<(), HostError> {
        let (completion, applied) = oneshot::channel();
        self.command_tx
            .send(HostCommand::BeginGo {
                status,
                join_allowed,
                completion,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        applied.await.map_err(|_| HostError::HostLoopGone)
    }

    pub async fn broadcast_status_ack(&self, status: NetworkStatus) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::BroadcastStatusAck(status))
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    /// Stamps the wall-clock instant at which the game first attempts this
    /// control frame. Repeated stalled-frame probes retain the first stamp.
    pub async fn control_tick_reached(
        &self,
        tick: Tick,
        control_rate: i32,
        target_fps: i32,
        reached_at: tokio::time::Instant,
    ) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::ControlTickReached {
                tick,
                control_rate,
                target_fps,
                reached_at,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    pub async fn control_tick_consumed(
        &self,
        tick: Tick,
        consumed_at: tokio::time::Instant,
        client_ids: Vec<ClientId>,
        reset_performance: bool,
    ) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::ControlTickConsumed {
                tick,
                consumed_at,
                client_ids,
                reset_performance,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    /// Report local arrival only for the barrier the caller actually drove.
    /// A higher remote acknowledgement may retarget the session before this
    /// command is processed, in which case the stale arrival must be ignored.
    pub async fn status_reached(
        &self,
        status: NetworkStatus,
        actual_control_tick: i32,
    ) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::StatusReached {
                status,
                actual_control_tick,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    /// Preserve the scenario-start path's existing ownership: FinalInit
    /// reaches whichever authoritative barrier is current when the command is
    /// processed. Runtime transitions use `status_reached` so stale reports
    /// cannot satisfy a later generation.
    pub async fn status_reached_current(&self) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::StatusReachedCurrent)
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    pub async fn submit_packet(
        &self,
        delivery: ControlDelivery,
        data: Vec<u8>,
    ) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::SubmitPacket { delivery, data })
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    pub async fn submit_exec_sync(&self, control_tick: Tick) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::ExecSync { control_tick })
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    pub async fn publish_join_snapshot(&self, snapshot: HostJoinSnapshot) -> Result<(), HostError> {
        self.command_tx
            .send(HostCommand::PublishJoinSnapshot(Box::new(snapshot)))
            .await
            .map_err(|_| HostError::HostLoopGone)
    }

    /// Publishes the dynamic produced at a synchronized runtime-join save
    /// boundary and wakes every accepted client still waiting for JoinData.
    pub async fn publish_runtime_dynamic(
        &self,
        dynamic: crate::LiveNetworkDynamic,
        dynamic_tick: i32,
        parameters: crate::JoinGameParametersEnvelope,
    ) -> Result<clonk_engine::NetworkResourceCore, HostError> {
        let (completion, published) = oneshot::channel();
        self.command_tx
            .send(HostCommand::PublishRuntimeDynamic {
                dynamic: Box::new(dynamic),
                dynamic_tick,
                parameters: Box::new(parameters),
                completion,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        published
            .await
            .map_err(|_| HostError::HostLoopGone)?
            .map_err(HostError::Resource)
    }

    /// Clears the currently advertised runtime dynamic and schedules its
    /// retained temporary resource for C++-style delayed cleanup.
    pub async fn remove_runtime_dynamic(&self) -> Result<bool, HostError> {
        let (completion, removed) = oneshot::channel();
        self.command_tx
            .send(HostCommand::RemoveRuntimeDynamic { completion })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        removed
            .await
            .map_err(|_| HostError::HostLoopGone)?
            .map_err(HostError::Resource)
    }

    /// Emergency-removes every accepted client for which JoinData has not
    /// been sent. Removal is a host-authored synchronized control, not a raw
    /// transport close.
    pub async fn fail_pending_join_data(
        &self,
        reason: clonk_engine::LegacyCString,
    ) -> Result<usize, HostError> {
        let (completion, removed) = oneshot::channel();
        self.command_tx
            .send(HostCommand::FailPendingJoinData { reason, completion })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        removed.await.map_err(|_| HostError::HostLoopGone)
    }

    pub async fn publish_player_resource(
        &self,
        request: crate::ClientPlayerResourceRequest,
    ) -> Result<clonk_engine::NetworkResourceCore, HostError> {
        let (completion, published) = oneshot::channel();
        self.command_tx
            .send(HostCommand::PublishPlayerResource {
                request,
                completion,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        published
            .await
            .map_err(|_| HostError::HostLoopGone)?
            .map_err(HostError::Resource)
    }

    /// Protects a complete resource before its source file is rewritten.
    pub async fn begin_resource_derive(
        &self,
        resource_id: i32,
        source_path: impl Into<PathBuf>,
        ownership: crate::ResourceFileOwnership,
    ) -> Result<crate::ResourceDerivation, HostError> {
        let (completion, derived) = oneshot::channel();
        self.command_tx
            .send(HostCommand::BeginResourceDerive {
                resource_id,
                source_path: source_path.into(),
                ownership,
                completion,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        derived
            .await
            .map_err(|_| HostError::HostLoopGone)?
            .map_err(HostError::Resource)
    }

    /// Publishes the rewritten source under a fresh ID and broadcasts its
    /// `PID_NetResDerive` core to every connected peer.
    pub async fn finish_resource_derive(
        &self,
        derivation: crate::ResourceDerivation,
    ) -> Result<clonk_engine::NetworkResourceCore, HostError> {
        let (completion, finished) = oneshot::channel();
        self.command_tx
            .send(HostCommand::FinishResourceDerive {
                derivation,
                completion,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        finished
            .await
            .map_err(|_| HostError::HostLoopGone)?
            .map_err(HostError::Resource)
    }

    pub async fn set_join_allowed(&self, allowed: bool) -> Result<(), HostError> {
        let (completion, applied) = oneshot::channel();
        self.command_tx
            .send(HostCommand::SetJoinAllowed {
                allowed,
                completion,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        applied.await.map_err(|_| HostError::HostLoopGone)
    }

    pub async fn set_password(
        &self,
        password: Option<clonk_engine::LegacyCString>,
    ) -> Result<(), HostError> {
        let (completion, applied) = oneshot::channel();
        self.command_tx
            .send(HostCommand::SetPassword {
                password,
                completion,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        applied.await.map_err(|_| HostError::HostLoopGone)
    }

    /// Re-runs the host's NAT-puncher handshake for the first address of
    /// each resolved family. Live Internet signup uses the same reliable-UDP
    /// socket as startup so the externally observed port remains stable.
    pub async fn init_netpunchers(&self, addresses: Vec<SocketAddr>) -> Result<(), HostError> {
        let (completion, initialized) = oneshot::channel();
        self.command_tx
            .send(HostCommand::InitNetpunchers {
                addresses,
                completion,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        initialized.await.map_err(|_| HostError::HostLoopGone)
    }

    pub async fn runtime_connections(&self) -> Result<Vec<RuntimeNetworkConnection>, HostError> {
        let (completion, inspected) = oneshot::channel();
        self.command_tx
            .send(HostCommand::InspectRuntimeConnections { completion })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        inspected.await.map_err(|_| HostError::HostLoopGone)
    }

    pub async fn lobby_client_telemetry(
        &self,
        client_ids: Vec<ClientId>,
    ) -> Result<RuntimeLobbyClientTelemetry, HostError> {
        let (completion, inspected) = oneshot::channel();
        self.command_tx
            .send(HostCommand::InspectLobbyClientTelemetry {
                client_ids,
                completion,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        inspected.await.map_err(|_| HostError::HostLoopGone)
    }

    pub async fn runtime_client_states(
        &self,
        tick: Tick,
        reset_performance: bool,
    ) -> Result<Vec<RuntimeNetworkClientState>, HostError> {
        let (completion, inspected) = oneshot::channel();
        self.command_tx
            .send(HostCommand::InspectRuntimeClientStates {
                tick,
                reset_performance,
                completion,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        inspected.await.map_err(|_| HostError::HostLoopGone)
    }

    pub async fn disconnect_runtime_connection(&self, connection_id: u32) -> Result<(), HostError> {
        let (completion, disconnected) = oneshot::channel();
        self.command_tx
            .send(HostCommand::DisconnectRuntimeConnection {
                connection_id,
                completion,
            })
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        if disconnected.await.map_err(|_| HostError::HostLoopGone)? {
            Ok(())
        } else {
            Err(HostError::ConnectionNotFound(connection_id))
        }
    }

    #[cfg(test)]
    async fn accepted_routes(&self) -> Vec<(u32, ClientId, u32)> {
        let (completion, routes) = oneshot::channel();
        self.command_tx
            .send(HostCommand::InspectAcceptedRoutes { completion })
            .await
            .expect("test host loop accepts route inspection");
        routes
            .await
            .expect("test host loop returns route inspection")
    }

    #[cfg(test)]
    async fn connected_clients(&self) -> Vec<ClientId> {
        let (completion, clients) = oneshot::channel();
        self.command_tx
            .send(HostCommand::InspectConnectedClients { completion })
            .await
            .expect("test host loop accepts client inspection");
        clients
            .await
            .expect("test host loop returns client inspection")
    }

    pub async fn shutdown(mut self) -> Result<(), HostError> {
        self.event_rx.take();
        if let Some(tx) = self.shutdown_tx.take() {
            let _ = tx.send(());
        }
        drop(self.command_tx);
        self.join_handle
            .await
            .map_err(|_| HostError::HostLoopGone)?;
        Ok(())
    }
}

#[derive(Debug, thiserror::Error)]
pub enum HostError {
    #[error("failed to bind listener: {0}")]
    Bind(#[from] io::Error),
    #[error("no host transport is available")]
    NoTransport,
    #[error("host loop terminated unexpectedly")]
    HostLoopGone,
    #[error("host resource initialization failed: {0}")]
    Resource(String),
    #[error("runtime connection {0} is not active")]
    ConnectionNotFound(u32),
}

#[derive(Debug, thiserror::Error)]
pub enum ClientError {
    #[error("failed to connect to host: {0}")]
    Connect(#[from] io::Error),
    #[error("host rejected the client password: {message:?}")]
    WrongPassword { message: clonk_engine::LegacyCString },
    #[error("handshake rejected: {0}")]
    Handshake(String),
    #[error("client resource publication failed: {0}")]
    Resource(String),
    #[error("failed to notify host before leaving: {0}")]
    GracefulPart(String),
    #[error("client loop terminated unexpectedly")]
    ClientLoopGone,
    #[error("runtime connection {0} is not active")]
    ConnectionNotFound(u32),
}

enum ClientAttemptError {
    Retryable(ClientError),
    WrongPassword(ClientError),
    Terminal(ClientError),
}

impl ClientAttemptError {
    fn into_error(self) -> ClientError {
        match self {
            Self::Retryable(error) | Self::WrongPassword(error) | Self::Terminal(error) => error,
        }
    }
}

impl From<ClientError> for ClientAttemptError {
    fn from(error: ClientError) -> Self {
        Self::Terminal(error)
    }
}

fn selected_puncher_addresses(addresses: &[SocketAddr]) -> Vec<SocketAddr> {
    let mut have_ipv4 = false;
    let mut have_ipv6 = false;
    addresses
        .iter()
        .copied()
        .map(crate::canonical_reliable_udp_peer_address)
        .filter(|address| match address {
            SocketAddr::V4(_) if !have_ipv4 => {
                have_ipv4 = true;
                true
            }
            SocketAddr::V6(_) if !have_ipv6 => {
                have_ipv6 = true;
                true
            }
            _ => false,
        })
        .collect()
}

enum ClientDialStream {
    Tcp(TcpStream),
    Udp(crate::ReliableUdpPeerStream),
}

type ClientConnectFuture =
    Pin<Box<dyn Future<Output = Result<ClientDialStream, io::Error>> + Send + 'static>>;

struct ClientDialAttempt {
    index: usize,
    future: Option<ClientConnectFuture>,
    result: Option<Result<ClientDialStream, io::Error>>,
}

struct ClientDialRace {
    attempts: Vec<ClientDialAttempt>,
    deadline: tokio::time::Instant,
}

impl ClientDialRace {
    fn new(
        addresses: impl IntoIterator<Item = crate::NetworkAddress>,
        tcp_available: bool,
        udp_handle: Option<crate::ReliableUdpSessionHandle>,
    ) -> Self {
        let mut seen_addresses = HashSet::new();
        Self {
            attempts: addresses
                .into_iter()
                .enumerate()
                .filter(|(_, address)| seen_addresses.insert(*address))
                .filter_map(|(index, address)| {
                    if address.is_ip_null() {
                        return None;
                    }
                    let endpoint = address.endpoint;
                    let future: ClientConnectFuture = match address.protocol {
                        crate::NetworkProtocol::Tcp => {
                            if !tcp_available {
                                return None;
                            }
                            Box::pin(async move {
                                TcpStream::connect(endpoint).await.map(ClientDialStream::Tcp)
                            })
                        }
                        crate::NetworkProtocol::Udp => {
                            let handle = udp_handle.clone()?;
                            Box::pin(async move {
                                handle.connect(endpoint).await.map(ClientDialStream::Udp)
                            })
                        }
                        crate::NetworkProtocol::Unknown(_) => return None,
                    };
                    Some(ClientDialAttempt {
                        index,
                        future: Some(future),
                        result: None,
                    })
                })
                .collect(),
            deadline: tokio::time::Instant::now() + HANDSHAKE_TIMEOUT,
        }
    }

    fn is_empty(&self) -> bool {
        self.attempts.is_empty()
    }

    async fn next(&mut self) -> Option<(usize, Result<ClientDialStream, io::Error>)> {
        if self.attempts.is_empty() {
            return None;
        }
        let ready = tokio::time::timeout_at(
            self.deadline,
            poll_fn(|context| {
                // Poll every fresh attempt before selecting a winner. This
                // starts the transports together while retaining stable input
                // order when multiple attempts are already ready.
                for attempt in &mut self.attempts {
                    let ready = attempt.future.as_mut().and_then(|future| {
                        match future.as_mut().poll(context) {
                            Poll::Ready(ready) => Some(ready),
                            Poll::Pending => None,
                        }
                    });
                    if let Some(ready) = ready {
                        attempt.result = Some(ready);
                        attempt.future = None;
                    }
                }
                self.attempts
                    .iter_mut()
                    .enumerate()
                    .find_map(|(position, attempt)| {
                        attempt.result.take().map(|result| (position, result))
                    })
                    .map_or(Poll::Pending, Poll::Ready)
            }),
        )
        .await;
        match ready {
            Ok((position, result)) => {
                let attempt = self.attempts.remove(position);
                Some((attempt.index, result))
            }
            Err(_) => {
                let index = self.attempts[0].index;
                self.attempts.clear();
                Some((
                    index,
                    Err(io::Error::new(
                        io::ErrorKind::TimedOut,
                        "connection attempt timed out",
                    )),
                ))
            }
        }
    }
}

struct PreparedClientMesh {
    tcp_listener: Option<TcpListener>,
    udp_hub: Option<crate::ReliableUdpSessionHub>,
    puncher_events: Option<mpsc::Receiver<crate::NetpuncherIoEvent>>,
    puncher_init: Arc<Mutex<ClientPuncherInitState>>,
    io_statistics: crate::NetworkIoStatistics,
}

struct ClientPuncherInitState {
    initializing: bool,
    observations: Vec<SocketAddr>,
}

impl PreparedClientMesh {
    fn udp_handle(&self) -> Option<crate::ReliableUdpSessionHandle> {
        self.udp_hub
            .as_ref()
            .map(crate::ReliableUdpSessionHub::handle)
    }
}

async fn prepare_client_mesh(
    config: &ClientConfig,
    require_udp: bool,
) -> Result<PreparedClientMesh, ClientError> {
    let io_statistics =
        crate::NetworkIoStatistics::new(network_statistics_now_ms());
    let mut first_bind_error = None;
    let tcp_listener = match config.mesh_tcp_bind_address {
        Some(bind_address) => match bind_client_mesh_tcp_listener(bind_address).await {
            Ok(listener) => Some(listener),
            Err(error) => {
                first_bind_error = Some(io::Error::new(
                    error.kind(),
                    format!("failed to bind client mesh TCP at {bind_address}: {error}"),
                ));
                None
            }
        },
        None => None,
    };
    let udp_bind_address = config.mesh_udp_bind_address.or_else(|| {
        (require_udp || !config.mesh_punchers.is_empty())
            .then_some(SocketAddr::from(([0_u16; 8], 0)))
    });
    let mut udp_hub = match udp_bind_address {
        Some(bind_address) => match crate::ReliableUdpSessionHub::bind_with_statistics(
            bind_address,
            io_statistics.clone(),
        ) {
            Ok(hub) => Some(hub),
            Err(error) => {
                first_bind_error.get_or_insert_with(|| {
                    io::Error::new(
                        error.kind(),
                        format!("failed to bind client mesh UDP at {bind_address}: {error}"),
                    )
                });
                None
            }
        },
        None => None,
    };
    let requested_transport = config.mesh_tcp_bind_address.is_some() || udp_bind_address.is_some();
    if requested_transport && tcp_listener.is_none() && udp_hub.is_none() {
        return Err(ClientError::Connect(first_bind_error.unwrap_or_else(|| {
            io::Error::new(
                io::ErrorKind::AddrNotAvailable,
                "no configured client network transport could be bound",
            )
        })));
    }
    let source_puncher_events = udp_hub
        .as_mut()
        .map(crate::ReliableUdpSessionHub::take_puncher_event_receiver);
    let udp_handle = udp_hub
        .as_ref()
        .map(crate::ReliableUdpSessionHub::handle);
    if let Some(handle) = udp_handle.as_ref() {
        for puncher in &config.mesh_punchers {
            let _ = handle
                .init_puncher(puncher.address, crate::NetpuncherRole::Client)
                .await;
        }
    }
    let puncher_init = Arc::new(Mutex::new(ClientPuncherInitState {
        initializing: true,
        observations: Vec::new(),
    }));
    let puncher_events = match (source_puncher_events, udp_handle) {
        (Some(mut source), Some(handle)) => {
            let (forward_tx, forward_rx) = mpsc::channel(64);
            let game_ids = crate::NetpuncherGameIds {
                ipv4: config
                    .mesh_punchers
                    .iter()
                    .find(|puncher| puncher.address.is_ipv4())
                    .map_or(0, |puncher| puncher.game_id),
                ipv6: config
                    .mesh_punchers
                    .iter()
                    .find(|puncher| puncher.address.is_ipv6())
                    .map_or(0, |puncher| puncher.game_id),
            };
            let pump_init = puncher_init.clone();
            tokio::spawn(async move {
                while let Some(event) = source.recv().await {
                    match &event {
                        crate::NetpuncherIoEvent::Connected {
                            family,
                            puncher_address,
                            ..
                        } => {
                            let family = *family;
                            let puncher_address = *puncher_address;
                            let initializing = {
                                let mut init = pump_init
                                    .lock()
                                    .expect("client puncher initialization lock poisoned");
                                if init.initializing {
                                    if let crate::NetpuncherIoEvent::Connected {
                                        observed_address, ..
                                    } = &event
                                    {
                                        init.observations.push(*observed_address);
                                    }
                                }
                                init.initializing
                            };
                            if initializing {
                                if let Some(packet) = crate::reduce_puncher_connect(
                                    crate::NetpuncherRole::Client,
                                    crate::NetpuncherRuntimeState::Initializing,
                                    family,
                                    game_ids,
                                ) {
                                    let _ = handle.send_puncher_packet(family, packet).await;
                                }
                            }
                            if forward_tx.send(event).await.is_err() {
                                let _ = handle.close_puncher(puncher_address).await;
                                break;
                            }
                        }
                        crate::NetpuncherIoEvent::Packet {
                            puncher_address,
                            packet: crate::NetpuncherPacket::AssignId { .. },
                            ..
                        } => {
                            let _ = puncher_address;
                        }
                        crate::NetpuncherIoEvent::Packet {
                            puncher_address,
                            packet: crate::NetpuncherPacket::ClientRequest { .. },
                            ..
                        } if pump_init
                            .lock()
                            .expect("client puncher initialization lock poisoned")
                            .initializing =>
                        {
                            let _ = puncher_address;
                        }
                        crate::NetpuncherIoEvent::Packet {
                            puncher_address, ..
                        } => {
                            let _ = handle.close_puncher(*puncher_address).await;
                        }
                    }
                }
            });
            Some(forward_rx)
        }
        (Some(source), None) => Some(source),
        (None, _) => None,
    };
    Ok(PreparedClientMesh {
        tcp_listener,
        udp_hub,
        puncher_events,
        puncher_init,
        io_statistics,
    })
}

/// UDP socket prepared before a host publishes its league Start reference.
/// A failed optional bind is retained so the host can surface its transport
/// error while continuing with TCP.
pub struct HostUdpBinding {
    hub: Option<crate::ReliableUdpSessionHub>,
    start_error: Option<String>,
    io_statistics: crate::NetworkIoStatistics,
}

impl HostUdpBinding {
    pub fn bind(config: &HostConfig) -> Self {
        let io_statistics =
            crate::NetworkIoStatistics::new(network_statistics_now_ms());
        let udp_bind_address = (config.configured_udp_port != Some(0))
            .then(|| {
                config.udp_bind_address.or_else(|| {
                    (!config.netpuncher_addresses.is_empty())
                        .then_some(SocketAddr::from(([0_u16; 8], 0)))
                })
            })
            .flatten();
        match udp_bind_address {
            Some(bind_address) => match crate::ReliableUdpSessionHub::bind_with_statistics(
                bind_address,
                io_statistics.clone(),
            ) {
                Ok(hub) => Self {
                    hub: Some(hub),
                    start_error: None,
                    io_statistics,
                },
                Err(error) => Self {
                    hub: None,
                    start_error: Some(format!(
                        "failed to start reliable-UDP listener at {bind_address}: {error}"
                    )),
                    io_statistics,
                },
            },
            None => Self {
                hub: None,
                start_error: None,
                io_statistics,
            },
        }
    }

    pub fn local_addr(&self) -> Option<SocketAddr> {
        self.hub
            .as_ref()
            .map(crate::ReliableUdpSessionHub::local_addr)
    }

    /// Retains the optional UDP bind diagnostic until another transport has
    /// been checked, so callers can fail only when both are unavailable.
    pub fn bind_error(&self) -> Option<&str> {
        self.start_error.as_deref()
    }
}

/// Starts the multiplayer host loop after binding its optional UDP socket.
pub async fn start_host_with_udp_binding(
    listener: TcpListener,
    config: HostConfig,
    udp_binding: HostUdpBinding,
) -> Result<HostHandle, HostError> {
    start_host_with_bindings(Some(listener), config, udp_binding).await
}

/// Starts the multiplayer host loop after independently preparing its TCP and
/// UDP transports. At least one binding must be live.
pub async fn start_host_with_bindings(
    listener: Option<TcpListener>,
    config: HostConfig,
    udp_binding: HostUdpBinding,
) -> Result<HostHandle, HostError> {
    start_host_with_udp_binding_and_backend(
        listener,
        config,
        udp_binding,
        &crate::upnp::RealPortMappingBackend,
    )
    .await
}

async fn start_host_with_udp_binding_and_backend(
    listener: Option<TcpListener>,
    config: HostConfig,
    udp_binding: HostUdpBinding,
    port_mapping_backend: &dyn crate::upnp::PortMappingBackend,
) -> Result<HostHandle, HostError> {
    if listener.is_none() && udp_binding.local_addr().is_none() {
        return Err(HostError::NoTransport);
    }
    let resource_backend = build_host_resource_backend(&config)?;
    let HostUdpBinding {
        hub: udp_hub,
        start_error: udp_start_error,
        io_statistics,
    } = udp_binding;
    let tcp_local_addr = listener
        .as_ref()
        .and_then(|listener| listener.local_addr().ok());
    let udp_local_addr = udp_hub
        .as_ref()
        .map(crate::ReliableUdpSessionHub::local_addr);
    let mapping_requests = host_port_mapping_requests(&config, tcp_local_addr, udp_local_addr);
    let active_port_mappings =
        (!mapping_requests.is_empty()).then(|| port_mapping_backend.start(&mapping_requests));
    let (command_tx, command_rx) = mpsc::channel::<HostCommand>(64);
    let (event_tx, event_rx) = mpsc::channel::<HostEvent>(64);
    let (shutdown_tx, shutdown_rx) = oneshot::channel();
    let task_io_statistics = io_statistics.clone();
    let join_handle = tokio::spawn(async move {
        run_host(
            listener,
            udp_hub,
            udp_start_error,
            config,
            resource_backend,
            task_io_statistics,
            command_rx,
            event_tx.clone(),
            shutdown_rx,
        )
        .await;
        if let Some(active_port_mappings) = active_port_mappings {
            active_port_mappings.shutdown().await;
        }
    });
    Ok(HostHandle {
        command_tx,
        event_rx: Some(event_rx),
        shutdown_tx: Some(shutdown_tx),
        join_handle,
        udp_local_addr,
        io_statistics,
    })
}

fn host_port_mapping_requests(
    config: &HostConfig,
    tcp_local_addr: Option<SocketAddr>,
    udp_local_addr: Option<SocketAddr>,
) -> Vec<crate::upnp::PortMappingRequest> {
    if !config.enable_upnp {
        return Vec::new();
    }

    let mut requests = Vec::with_capacity(2);
    let tcp_port = tcp_local_addr
        .map(|address| config.configured_tcp_port.unwrap_or(address.port()))
        .filter(|port| *port != 0);
    if let Some(internal_port) = tcp_port {
        requests.push(crate::upnp::PortMappingRequest {
            protocol: crate::upnp::PortMappingProtocol::Tcp,
            internal_port,
            external_port: 0,
        });
    }
    let udp_port = udp_local_addr
        .map(|address| config.configured_udp_port.unwrap_or(address.port()))
        .filter(|port| *port != 0);
    if let Some(internal_port) = udp_port {
        requests.push(crate::upnp::PortMappingRequest {
            protocol: crate::upnp::PortMappingProtocol::Udp,
            internal_port,
            external_port: 0,
        });
    }
    requests
}

/// Starts the multiplayer host loop.
pub async fn start_host(
    listener: TcpListener,
    config: HostConfig,
) -> Result<HostHandle, HostError> {
    let udp_binding = HostUdpBinding::bind(&config);
    start_host_with_udp_binding(listener, config, udp_binding).await
}

fn build_host_resource_backend(
    config: &HostConfig,
) -> Result<Option<crate::ResourceTransferBackend>, HostError> {
    let Some(directory) = config.resource_directory.as_ref() else {
        if config.resource_files.is_empty() {
            return Ok(None);
        }
        return Err(HostError::Resource(
            "host resource files require a network working directory".to_string(),
        ));
    };
    let mut backend = crate::ResourceTransferBackend::new(0, directory)
        .map_err(|error| HostError::Resource(error.to_string()))?;
    for resource in &config.resource_files {
        backend
            .register_hosted_resource(
                resource.core.clone(),
                &resource.path,
                resource.ownership,
                resource.binary_compatible,
            )
            .map_err(|error| HostError::Resource(error.to_string()))?;
    }
    Ok(Some(backend))
}

/// Connects to an existing host and returns a handle for interaction.
pub async fn connect_client(
    addr: SocketAddr,
    config: ClientConfig,
) -> Result<ClientHandle, ClientError> {
    connect_client_addresses(
        [crate::NetworkAddress::new(
            crate::NetworkProtocol::Tcp,
            addr,
        )],
        config,
    )
    .await
}

/// Connects one logical client over both session transports. Reliable UDP is
/// preferred for message traffic, while TCP is preferred for resource data;
/// either accepted route remains a fallback if the other one closes.
pub async fn connect_dual_client(
    tcp_addr: SocketAddr,
    udp_addr: SocketAddr,
    config: ClientConfig,
) -> Result<ClientHandle, ClientError> {
    connect_client_from_inner_with_udp(TcpStream::connect(tcp_addr), config, None, Some(udp_addr))
        .await
}

/// Connects to an existing host through C4NetIOUDP's reliable packet stream.
pub async fn connect_udp_client(
    addr: SocketAddr,
    config: ClientConfig,
) -> Result<ClientHandle, ClientError> {
    connect_client_addresses(
        [crate::NetworkAddress::new(
            crate::NetworkProtocol::Udp,
            addr,
        )],
        config,
    )
    .await
}

/// Connects through the first admitted route from an already prepared C++
/// join-attempt list.
///
/// Callers joining from a game reference prepare that list with
/// [`crate::NetworkGameReference::join_attempts`]. TCP and reliable-UDP
/// transports are established concurrently, while their admission handshakes
/// are serialized so only one route can create the logical client.
pub async fn connect_client_addresses(
    addresses: impl IntoIterator<Item = crate::NetworkAddress>,
    config: ClientConfig,
) -> Result<ClientHandle, ClientError> {
    let addresses = addresses.into_iter().collect::<Vec<_>>();
    let mut secondary_tcp_addr = addresses
        .iter()
        .find(|address| {
            matches!(address.protocol, crate::NetworkProtocol::Tcp) && !address.is_ip_null()
        })
        .map(|address| address.endpoint);
    let mut secondary_udp_addr = addresses
        .iter()
        .find(|address| {
            matches!(address.protocol, crate::NetworkProtocol::Udp) && !address.is_ip_null()
        })
        .map(|address| address.endpoint);
    let mut client_mesh = prepare_client_mesh(&config, secondary_udp_addr.is_some()).await?;
    let tcp_available = config.mesh_tcp_bind_address.is_none()
        || client_mesh.tcp_listener.is_some();
    if !tcp_available {
        secondary_tcp_addr = None;
    }
    let udp_handle = client_mesh.udp_handle();
    if udp_handle.is_none() {
        secondary_udp_addr = None;
    }
    let mut dials = ClientDialRace::new(addresses, tcp_available, udp_handle);
    if dials.is_empty() {
        return Err(ClientError::Connect(io::Error::new(
            io::ErrorKind::Unsupported,
            "join address list contains no supported TCP or reliable-UDP endpoint",
        )));
    }
    let mut failures = Vec::new();
    let mut wrong_password: Option<(usize, ClientError)> = None;
    while let Some((index, result)) = dials.next().await {
        let stream = match result {
            Ok(stream) => stream,
            Err(error) => {
                failures.push((index, ClientError::Connect(error)));
                continue;
            }
        };
        let admission = match stream {
            ClientDialStream::Tcp(stream) => {
                stream.set_nodelay(true).ok();
                let peer_addr = stream.peer_addr().ok();
                connect_client_stream_attempt(
                    stream,
                    peer_addr,
                    crate::NetworkProtocol::Tcp,
                    config.clone(),
                    None,
                    secondary_udp_addr,
                    None,
                    &mut client_mesh,
                )
                .await
            }
            ClientDialStream::Udp(stream) => {
                let peer_addr = stream.peer_addr();
                match stream.bind_statistics_connection(0).await {
                    Ok(()) => {
                        connect_client_stream_attempt(
                            stream,
                            Some(peer_addr),
                            crate::NetworkProtocol::Udp,
                            config.clone(),
                            None,
                            None,
                            secondary_tcp_addr,
                            &mut client_mesh,
                        )
                        .await
                    }
                    Err(error) => {
                        Err(ClientAttemptError::Retryable(ClientError::Connect(error)))
                    }
                }
            }
        };
        match admission {
            Ok(client) => return Ok(client),
            Err(ClientAttemptError::Retryable(error)) => failures.push((index, error)),
            Err(ClientAttemptError::WrongPassword(error)) => {
                if wrong_password
                    .as_ref()
                    .is_none_or(|(previous_index, _)| index < *previous_index)
                {
                    wrong_password = Some((index, error));
                }
            }
            Err(ClientAttemptError::Terminal(error)) => return Err(error),
        }
    }
    if let Some((_, error)) = wrong_password {
        return Err(error);
    }
    failures.sort_by_key(|(index, _)| *index);
    Err(failures
        .into_iter()
        .next()
        .expect("a completed dial race retains its failure")
        .1)
}

#[cfg(test)]
async fn connect_client_from<F>(
    connection: F,
    config: ClientConfig,
) -> Result<ClientHandle, ClientError>
where
    F: Future<Output = Result<TcpStream, io::Error>>,
{
    connect_client_from_inner(connection, config, None).await
}

#[cfg(test)]
async fn connect_client_from_inner<F>(
    connection: F,
    config: ClientConfig,
    liveness: Option<ConnectionLivenessState>,
) -> Result<ClientHandle, ClientError>
where
    F: Future<Output = Result<TcpStream, io::Error>>,
{
    connect_client_from_inner_with_udp(connection, config, liveness, None).await
}

async fn connect_client_from_inner_with_udp<F>(
    connection: F,
    config: ClientConfig,
    liveness: Option<ConnectionLivenessState>,
    secondary_udp_addr: Option<SocketAddr>,
) -> Result<ClientHandle, ClientError>
where
    F: Future<Output = Result<TcpStream, io::Error>>,
{
    let mut client_mesh = prepare_client_mesh(&config, secondary_udp_addr.is_some()).await?;
    let stream = tokio::time::timeout(HANDSHAKE_TIMEOUT, connection)
        .await
        .map_err(|_| {
            ClientError::Connect(io::Error::new(
                io::ErrorKind::TimedOut,
                "connection attempt timed out",
            ))
        })?
        .map_err(ClientError::Connect)?;
    stream.set_nodelay(true).ok();
    let host_peer_addr = stream.peer_addr().ok();

    connect_client_stream_attempt(
        stream,
        host_peer_addr,
        crate::NetworkProtocol::Tcp,
        config,
        liveness,
        secondary_udp_addr,
        None,
        &mut client_mesh,
    )
    .await
    .map_err(ClientAttemptError::into_error)
}

async fn connect_client_stream_attempt<S>(
    stream: S,
    host_peer_addr: Option<SocketAddr>,
    host_protocol: crate::NetworkProtocol,
    config: ClientConfig,
    liveness: Option<ConnectionLivenessState>,
    secondary_udp_addr: Option<SocketAddr>,
    secondary_tcp_addr: Option<SocketAddr>,
    client_mesh: &mut PreparedClientMesh,
) -> Result<ClientHandle, ClientAttemptError>
where
    S: AsyncRead + AsyncWrite + Unpin + Send + 'static,
{
    let io_statistics = client_mesh.io_statistics.clone();
    let ClientConfig {
        name,
        group_maker,
        kind,
        compatibility_build,
        password,
        resource_directory,
        mut bootstrap_local_candidates,
        local_system_path,
        local_resource_roots,
        mesh_tcp_bind_address: _,
        mesh_udp_bind_address: _,
        mesh_punchers: _,
    } = config;
    let wire_name = clonk_engine::LegacyCString::from_bytes(name.into_bytes()).ok_or_else(|| {
        ClientError::Handshake("client name contains an interior NUL".to_string())
    })?;
    let local_core = clonk_engine::ClientCoreControlData {
        client_id: -1,
        activated: matches!(kind, ParticipantKind::Player),
        observer: matches!(kind, ParticipantKind::Observer),
        name: wire_name.clone(),
        nick: wire_name,
        lobby_ready: false,
    };
    let primary_connection_id = 0;
    let request = crate::ConnectionRequest {
        core: local_core.clone(),
        build: compatibility_build,
        password: password.clone(),
        connection_id: primary_connection_id,
    };
    let mut transport = crate::ControlTransport::new(stream);
    if matches!(host_protocol, crate::NetworkProtocol::Tcp) {
        transport.set_statistics(
            io_statistics.open_connection(primary_connection_id, crate::NetworkProtocol::Tcp),
        );
    }
    let bootstrap = match liveness {
        Some(liveness) => {
            crate::connection_handshake::run_client_connection_handshake_with_liveness(
                &mut transport,
                request,
                liveness,
            )
            .await
        }
        None => run_client_connection_handshake(&mut transport, request).await,
    }
    .map_err(|error| match error {
        crate::ConnectionHandshakeError::PeerRejection {
            message,
            wrong_password: true,
        } => ClientAttemptError::WrongPassword(ClientError::WrongPassword { message }),
        error => {
            let retryable = matches!(
                &error,
                crate::ConnectionHandshakeError::Transport(_)
                    | crate::ConnectionHandshakeError::AdmissionTimeout
                    | crate::ConnectionHandshakeError::PingTimeout
            );
            let error = ClientError::Handshake(error.to_string());
            if retryable {
                ClientAttemptError::Retryable(error)
            } else {
                ClientAttemptError::Terminal(error)
            }
        }
    })?;
    let primary_local_connection_id = bootstrap.local_connection_id;
    let primary_remote_connection_id = bootstrap.remote_connection_id;
    debug_assert_eq!(primary_local_connection_id, primary_connection_id);
    let primary_liveness = bootstrap.liveness.clone();
    let host_core = bootstrap.peer_core.clone();
    let mut join_data = bootstrap.join_data;
    if join_data.client_id < 0 {
        return Err(ClientError::Handshake(
            "host did not assign a client id in JoinData".to_string(),
        )
        .into());
    }
    if !matches!(
        join_data.status.state,
        NETWORK_STATE_LOBBY | NETWORK_STATE_PAUSE | NETWORK_STATE_GO
    ) {
        return Err(ClientError::Handshake(format!(
            "host sent invalid JoinData status {}",
            join_data.status.state
        ))
        .into());
    }
    client_mesh
        .puncher_init
        .lock()
        .expect("client puncher initialization lock poisoned")
        .initializing = false;
    let existing_clients = JoinClientRegistrySnapshot {
        clients: vec![local_core],
        local_client_id: Some(-1),
    };
    join_data.parameters.clients = reconcile_join_client_registry(
        &existing_clients,
        join_data.parameters.clients.clone(),
        join_data.client_id,
    )
    .ok_or_else(|| {
        ClientError::Handshake("assigned local client is missing from JoinData".to_string())
    })?;
    let assigned_local_core = join_data
        .parameters
        .clients
        .clients
        .iter()
        .find(|core| core.client_id == join_data.client_id)
        .cloned()
        .ok_or_else(|| {
            ClientError::Handshake(
                "assigned local client core disappeared from JoinData".to_string(),
            )
        })?;
    let start_control_tick = Tick::try_from(join_data.start_control_tick).map_err(|_| {
        ClientError::Handshake(format!(
            "host sent negative JoinData control tick {}",
            join_data.start_control_tick
        ))
    })?;
    let mut resource_state = ClientResourceState::new(
        &join_data,
        bootstrap.peer_core.client_id,
        bootstrap.pending_resources,
        bootstrap.pending_controls,
        bootstrap.liveness,
        resource_directory.clone(),
    )
    .map_err(ClientError::Handshake)?;
    resource_state.initial_ready_checks = bootstrap.pending_ready_checks;
    resource_state.initial_lobby_countdowns = bootstrap.pending_lobby_countdowns;
    send_client_control_request(&mut transport, start_control_tick)
        .await
        .map_err(|error| {
            ClientError::Handshake(format!(
                "failed to initialize control after JoinData: {error}"
            ))
        })?;
    resource_state.next_control_request_at =
        tokio::time::Instant::now() + CONTROL_REQUEST_INTERVAL;
    bootstrap_local_candidates.extend_from_roots(&join_data, &local_resource_roots);
    if let Some(system_path) = local_system_path {
        for system in join_data
            .parameters
            .game_resources
            .iter()
            .filter(|core| core.resource_type == crate::HostResourceType::System as u8)
        {
            bootstrap_local_candidates.prioritize(system.id, system_path.clone());
        }
    }
    let standalone_directory = resource_directory
        .as_deref()
        .unwrap_or_else(|| std::path::Path::new("Network"));
    let bootstrap_resolver = crate::client_bootstrap::ClientBootstrapResolver::new_with_group_maker(
        &bootstrap_local_candidates,
        standalone_directory.to_path_buf(),
        group_maker,
    );
    let mut initialized_game_resources = 0;
    for core in &join_data.parameters.game_resources {
        if resource_state
            .resolve_and_add_bootstrap_resource(
                &bootstrap_resolver,
                crate::ClientBootstrapResourceRole::GameResource,
                core,
            )
            .is_err()
        {
            break;
        }
        initialized_game_resources += 1;
    }
    resource_state
        .resolve_and_add_bootstrap_resource(
            &bootstrap_resolver,
            crate::ClientBootstrapResourceRole::Dynamic,
            &join_data.dynamic,
        )
        .map_err(ClientError::Handshake)?;
    for player in join_data
        .parameters
        .player_infos
        .clients
        .iter_mut()
        .flat_map(|client| &mut client.players)
    {
        let flags = player.flags;
        if flags & clonk_engine::PLAYER_INFO_FLAG_REMOVED != 0
            || flags & clonk_engine::PLAYER_INFO_FLAG_HAS_RESOURCE == 0
        {
            continue;
        }
        if flags & clonk_engine::PLAYER_INFO_FLAG_IN_SCENARIO_FILE != 0 {
            crate::client_bootstrap::clear_player_resource(player);
            continue;
        }
        let Some(core) = player.resource.clone() else {
            crate::client_bootstrap::clear_player_resource(player);
            continue;
        };
        match resource_state.resolve_and_add_bootstrap_resource(
            &bootstrap_resolver,
            crate::ClientBootstrapResourceRole::Player,
            &core,
        ) {
            Ok(
                ClientBootstrapRegistration::AlreadyPresent
                | ClientBootstrapRegistration::Registered,
            ) => {}
            Ok(ClientBootstrapRegistration::UnavailableNonLoadable) | Err(_) => {
                crate::client_bootstrap::clear_player_resource(player);
            }
        }
    }
    let client_id = join_data.client_id as ClientId;
    let mesh_tcp_listener = client_mesh.tcp_listener.take();
    let mesh_udp_hub = client_mesh.udp_hub.take();
    let mesh_tcp_local_addr = mesh_tcp_listener
        .as_ref()
        .and_then(|listener| listener.local_addr().ok());
    let mesh_udp_local_addr = mesh_udp_hub
        .as_ref()
        .map(crate::ReliableUdpSessionHub::local_addr);
    let mesh_puncher_events = client_mesh.puncher_events.take();
    let mut client_addresses = join_data
        .parameters
        .clients
        .clients
        .iter()
        .map(|core| (core.client_id, Vec::new()))
        .collect::<BTreeMap<_, _>>();
    for packet in &bootstrap.pending_addresses {
        if !client_addresses.contains_key(&packet.client_id) {
            continue;
        }
        let packet = host_peer_addr
            .map(|peer| packet.announcement_for_peer(peer))
            .unwrap_or(*packet);
        crate::append_received_address(
            client_addresses.entry(packet.client_id).or_default(),
            packet.address,
        );
    }
    let mesh_interface_endpoints = crate::client_mesh::client_mesh_os_interface_endpoints();
    let mesh_interface_ids = mesh_interface_endpoints
        .iter()
        .filter_map(|endpoint| match endpoint {
            SocketAddr::V6(endpoint)
                if endpoint.ip().is_unicast_link_local() && endpoint.scope_id() != 0 =>
            {
                Some(endpoint.scope_id())
            }
            _ => None,
        })
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    for address in crate::client_mesh::client_mesh_local_addresses(
        mesh_tcp_local_addr,
        mesh_udp_local_addr,
        mesh_interface_endpoints,
    ) {
        crate::append_received_address(
            client_addresses.entry(join_data.client_id).or_default(),
            address,
        );
    }
    if let Some(host_peer_addr) = host_peer_addr {
        let host_address = crate::NetworkAddress::new(host_protocol, host_peer_addr);
        crate::append_received_address(
            client_addresses
                .entry(bootstrap.peer_core.client_id)
                .or_default(),
            host_address,
        );
    }
    let client_cores = join_data
        .parameters
        .clients
        .clients
        .iter()
        .cloned()
        .map(|core| (core.client_id, core))
        .collect::<BTreeMap<_, _>>();
    let mut mesh_peers = client_addresses
        .keys()
        .copied()
        .map(|peer_id| (peer_id, crate::ClientMeshPeerState::new()))
        .collect::<BTreeMap<_, _>>();
    for (peer_id, addresses) in &client_addresses {
        let peer = mesh_peers
            .get_mut(peer_id)
            .expect("address owner has mesh state");
        for address in addresses {
            peer.add_address(*address, Duration::ZERO);
        }
    }
    let initial_puncher_observations = {
        let mut observations = client_mesh
            .puncher_init
            .lock()
            .expect("client puncher initialization lock poisoned");
        std::mem::take(&mut observations.observations)
    };
    for observed_address in initial_puncher_observations {
        let update = mesh_peers
            .entry(join_data.client_id)
            .or_default()
            .add_address_from_puncher(
                observed_address,
                mesh_udp_local_addr.map_or(0, |address| address.port()),
                mesh_tcp_local_addr.map_or(0, |address| address.port()),
                Duration::ZERO,
            );
        for address in update.announcements {
            let addresses = client_addresses.entry(join_data.client_id).or_default();
            if !addresses.contains(&address) {
                addresses.insert(0, address);
            }
        }
    }
    let address_announcements = client_addresses
        .iter()
        .flat_map(|(client_id, addresses)| {
            addresses.iter().filter_map(move |address| {
                let address = host_peer_addr
                    .and_then(|peer| address_for_peer(*address, peer))
                    .or((host_peer_addr.is_none()).then_some(*address))?;
                Some(crate::AddressPacket {
                    client_id: *client_id,
                    address,
                })
            })
        })
        .collect();
    send_client_address_announcements(&mut transport, address_announcements)
        .await
        .map_err(|error| {
            ClientError::Handshake(format!(
                "failed to announce addresses after JoinData: {error}"
            ))
        })?;
    resource_state
        .resolve_and_add_bootstrap_resource(
            &bootstrap_resolver,
            crate::ClientBootstrapResourceRole::Scenario,
            &join_data.parameters.scenario,
        )
        .map_err(ClientError::Handshake)?;
    for core in join_data
        .parameters
        .game_resources
        .iter()
        .skip(initialized_game_resources)
    {
        resource_state
            .resolve_and_add_bootstrap_resource(
                &bootstrap_resolver,
                crate::ClientBootstrapResourceRole::GameResource,
                core,
            )
            .map_err(ClientError::Handshake)?;
    }
    resource_state.retain_resource_resolver(bootstrap_resolver);

    // Keep the admitted primary route's Ping/Pong and timeout state live while
    // an explicitly requested second transport completes its own handshake.
    let mut routes = ClientRouteManager::new();
    routes.add_route(
        primary_local_connection_id,
        primary_remote_connection_id,
        host_protocol,
        host_peer_addr,
        transport,
        primary_liveness,
    );
    let udp_reconnect_addr = secondary_udp_addr.or_else(|| {
        matches!(host_protocol, crate::NetworkProtocol::Udp)
            .then_some(host_peer_addr)
            .flatten()
    });
    let tcp_reconnect_addr = secondary_tcp_addr.or_else(|| {
        matches!(host_protocol, crate::NetworkProtocol::Tcp)
            .then_some(host_peer_addr)
            .flatten()
    });
    let connection_ids = Arc::new(AtomicU32::new(
        primary_local_connection_id.wrapping_add(1),
    ));
    let mesh_udp_handle = mesh_udp_hub
        .as_ref()
        .map(crate::ReliableUdpSessionHub::handle);
    let host_request_template = ClientHandshakeRequestTemplate::new(
        assigned_local_core.clone(),
        compatibility_build,
        password,
    );
    let mut udp_reconnect = udp_reconnect_addr
        .zip(mesh_udp_handle)
        .map(|(addr, handle)| ClientUdpReconnect {
            addr,
            handle,
            request_template: host_request_template.clone(),
            expected_host_core: host_core.clone(),
            connection_ids: connection_ids.clone(),
        });
    let mut tcp_reconnect = tcp_reconnect_addr.map(|addr| ClientTcpReconnect {
        addr,
        request_template: host_request_template,
        expected_host_core: host_core.clone(),
        connection_ids: connection_ids.clone(),
        io_statistics: io_statistics.clone(),
    });
    let pending_secondary = if secondary_udp_addr.is_some() {
        udp_reconnect.as_mut().map(ClientUdpReconnect::start)
    } else {
        None
    };
    let pending_tcp = if secondary_tcp_addr.is_some() {
        tcp_reconnect.as_mut().map(ClientTcpReconnect::start)
    } else {
        None
    };

    let (command_tx, command_rx) = mpsc::channel::<ClientCommand>(64);
    let (event_tx, event_rx) = mpsc::channel::<ClientEvent>(64);
    let (shutdown_tx, shutdown_rx) = oneshot::channel();
    let join_handle = tokio::spawn(run_client_loop_with_routes(
        routes,
        io_statistics.clone(),
        command_rx,
        event_tx,
        shutdown_rx,
        host_peer_addr,
        client_addresses,
        client_cores,
        mesh_peers,
        ClientHandshakeRequestTemplate::new(
            assigned_local_core,
            compatibility_build,
            clonk_engine::LegacyCString::default(),
        ),
        connection_ids,
        mesh_interface_ids,
        mesh_tcp_listener,
        mesh_udp_hub,
        mesh_puncher_events,
        mesh_tcp_local_addr.map_or(0, |address| address.port()),
        mesh_udp_local_addr.map_or(0, |address| address.port()),
        resource_state,
        udp_reconnect,
        pending_secondary,
        tcp_reconnect,
        pending_tcp,
    ));
    Ok(ClientHandle {
        command_tx,
        event_rx: Some(event_rx),
        shutdown_tx: Some(shutdown_tx),
        join_handle,
        client_id,
        join_data: Some(join_data),
        io_statistics,
    })
}

struct ConnectedClientRoute<S> {
    local_connection_id: u32,
    remote_connection_id: u32,
    peer_addr: SocketAddr,
    transport: crate::ControlTransport<S>,
    liveness: ConnectionLivenessState,
}

type PendingClientRoute = tokio::task::JoinHandle<
    Result<ConnectedClientRoute<crate::ReliableUdpPeerStream>, ClientError>,
>;
type PendingTcpClientRoute =
    tokio::task::JoinHandle<Result<ConnectedClientRoute<TcpStream>, ClientError>>;

#[derive(Clone)]
struct ClientHandshakeRequestTemplate {
    local_core: clonk_engine::ClientCoreControlData,
    compatibility_build: i32,
    password: clonk_engine::LegacyCString,
}

impl ClientHandshakeRequestTemplate {
    fn new(
        local_core: clonk_engine::ClientCoreControlData,
        compatibility_build: i32,
        password: clonk_engine::LegacyCString,
    ) -> Self {
        Self {
            local_core,
            compatibility_build,
            password,
        }
    }

    fn connection_request(&self, connection_id: u32) -> crate::ConnectionRequest {
        crate::ConnectionRequest {
            core: self.local_core.clone(),
            build: self.compatibility_build,
            password: self.password.clone(),
            connection_id,
        }
    }
}

enum ConnectedMeshRoute {
    Tcp {
        peer_id: ClientId,
        initiator_id: ClientId,
        peer_core: clonk_engine::ClientCoreControlData,
        route: ConnectedClientRoute<TcpStream>,
    },
    Udp {
        peer_id: ClientId,
        initiator_id: ClientId,
        peer_core: clonk_engine::ClientCoreControlData,
        route: ConnectedClientRoute<crate::ReliableUdpPeerStream>,
    },
}

type MeshDialKey = (i32, u8, SocketAddr);

struct MeshRouteCompletion {
    dial_key: Option<MeshDialKey>,
    result: Result<ConnectedMeshRoute, ClientError>,
}

async fn connect_mesh_tcp_route(
    peer_id: ClientId,
    addr: SocketAddr,
    request_template: ClientHandshakeRequestTemplate,
    expected_peer_core: clonk_engine::ClientCoreControlData,
    connection_id: u32,
    io_statistics: crate::NetworkIoStatistics,
) -> Result<ConnectedMeshRoute, ClientError> {
    let initiator_id =
        ClientId::try_from(request_template.local_core.client_id).unwrap_or(ClientId::MAX);
    let stream = tokio::time::timeout(HANDSHAKE_TIMEOUT, TcpStream::connect(addr))
        .await
        .map_err(|_| {
            ClientError::Connect(io::Error::new(
                io::ErrorKind::TimedOut,
                "mesh TCP connection attempt timed out",
            ))
        })?
        .map_err(ClientError::Connect)?;
    stream.set_nodelay(true).ok();
    let peer_addr = stream.peer_addr().map_err(ClientError::Connect)?;
    let mut transport = crate::ControlTransport::with_statistics(
        stream,
        io_statistics.open_connection(connection_id, crate::NetworkProtocol::Tcp),
    );
    let handshake = crate::connection_handshake::run_known_peer_connection_handshake(
        &mut transport,
        request_template.connection_request(connection_id),
        &expected_peer_core,
    )
    .await
    .map_err(|error| ClientError::Handshake(error.to_string()))?;
    Ok(ConnectedMeshRoute::Tcp {
        peer_id,
        initiator_id,
        peer_core: handshake.peer_core,
        route: ConnectedClientRoute {
            local_connection_id: handshake.local_connection_id,
            remote_connection_id: handshake.remote_connection_id,
            peer_addr,
            transport,
            liveness: handshake.liveness,
        },
    })
}

